def enc(v):
    try:
        iv = int(v)
        if str(iv) == v and -(2 ** 63) <= iv < 2 ** 63:
            return "int"
    except ValueError:
        pass
    return "embstr" if len(v.encode("utf-8")) <= 44 else "raw"

samples = ["123", "hello", "x" * 50]
for v in samples:
    print("TYPE string | OBJECT ENCODING %-8s -> %s" % (repr(v[:8]), enc(v)))
print("TYPE 反映顶层对象类型, OBJECT ENCODING 反映底层编码(二者不同)")
